import 'package:flutter_test/flutter_test.dart';import 'package:internal_chat/models/api_result.dart';import 'package:internal_chat/models/chat_message.dart';import 'package:internal_chat/models/conversation.dart';import 'package:internal_chat/models/page_result.dart';import 'package:internal_chat/modules/chat/chat_controller.dart';import 'package:internal_chat/repositories/chat_repository.dart';
class ContractChatRepository implements ChatRepository{bool listed=false,sent=false; @override Stream<ChatMessage> get incomingMessages=>const Stream.empty(); @override Future<void> initialize()async{} @override Future<void> dispose()async{}@override Future<ApiResult<PageResult<Conversation>>> conversations(PageRequest request)async{listed=true;return const ApiSuccess(PageResult(items:[Conversation(id:'c',title:'Through contract',kind:ConversationKind.group)]));}@override Future<ApiResult<PageResult<ChatMessage>>> messages(String id,PageRequest request)async=>const ApiSuccess(PageResult(items:[]));@override Future<ApiResult<ChatMessage>> sendMessage({required String conversationId,required String body,required String clientId})async{sent=true;return ApiSuccess(ChatMessage(id:'server-id',conversationId:conversationId,senderId:'current-user',senderDisplayName:'You',body:body,sentAt:DateTime(2026)));}}
void main(){test('chat controller lists and sends through repository interface',()async{final repository=ContractChatRepository();final controller=ChatController(repository);controller.onInit();await controller.loadConversations();expect(repository.listed,isTrue);expect(controller.conversations.single.title,'Through contract');await controller.send('c','hello');expect(repository.sent,isTrue);expect(controller.messages.single.id,'server-id');controller.onClose();});test('send delegates to repository contract',()async{final repository=ContractChatRepository();final controller=ChatController(repository);await controller.send('c','message');expect(repository.sent,isTrue);});}
